/** Brand icon for a platform id; a globe for "website" or anything unknown. */
export function SocialIcon({
  platform,
  size = 20,
  ...props
}: IconProps & { platform: string }) {
  const d = PATHS[platform];

  if (!d) return <Globe aria-hidden="true" size={size} />;

  return (
    <svg
      aria-hidden="true"
      fill="currentColor"
      height={size}
      viewBox="0 0 24 24"
      width={size}
      {...props}
    >
      <path d={d} />
    </svg>
  );
}
